INSERT INTO `attendancerequests` (`RequestID`, `EmployeeID`, `RequestDate`, `RequestType`, `Reason`, `Document`, `Status`, `createdAt`, `updatedAt`) VALUES
(1, 14, '2024-10-17', 'Punch In', 'Hi Nithin, I have clocked in after 12pm on 17-oct-2024, but I got notification that \"Leave has been deducted\", can you please check and give me attendance.', NULL, 'Deleted', '2024-10-18 06:43:28', '2024-10-18 07:41:55'),
(2, 19, '2024-10-18', 'Punch In', 'Leave deducted for not clocking in today. Kindly approve the attendance', NULL, 'Approved', '2024-10-18 11:00:39', '2024-10-21 04:35:16'),
(3, 12, '2024-10-22', 'Punch In', 'I didn\'t Clock in today morning', NULL, 'Approved', '2024-10-22 08:05:14', '2024-10-23 04:17:50'),
(4, 18, '2024-10-22', 'Punch In', 'I was on leave... I am going to apply leave so please approve my leave request', NULL, 'Approved', '2024-10-23 04:18:28', '2024-10-23 04:19:39'),
(5, 12, '2024-11-25', 'Punch In', 'I have been in testing call with boomi and then vishal call continued. Sorry, forgot to clock in.', NULL, 'Approved', '2024-11-25 10:06:40', '2024-11-27 04:09:56'),
(6, 19, '2024-11-28', 'Punch In', 'Train delayed and didn\'t have access to laptop to mark attendance.', NULL, 'Approved', '2024-11-28 08:46:04', '2024-12-02 11:15:01'),
(7, 17, '2024-11-28', 'Punch In', 'Missed to sign in', NULL, 'Approved', '2024-11-28 09:14:47', '2024-12-02 11:15:59'),
(8, 16, '2024-11-29', 'Punch In', 'Thanksgiving 2024 client holiday', NULL, 'Deleted', '2024-12-04 08:01:13', '2024-12-05 05:07:43'),
(9, 12, '2024-12-12', 'Punch In', 'I have not logged in as i joined late today. Please mark attendance for me Thank you.', NULL, 'Approved', '2024-12-12 11:26:41', '2024-12-13 06:23:42'),
(10, 12, '2024-12-11', 'Punch In', 'I have been working on calls back-to-back and didn\'t check schedule to login. Please mark attendance for me Thank you.', NULL, 'Approved', '2024-12-12 11:27:32', '2024-12-13 06:23:50'),
(11, 12, '2024-12-19', 'Punch In', 'I joined late yesterday and I had call with others on boomi and cascade for follow ups on daily work. I realised to check in but it was past 1:30 pm.\r\nThank you', NULL, 'Approved', '2024-12-20 04:05:06', '2025-01-02 17:16:09'),
(12, 12, '2024-12-23', 'Punch In', 'I have been in calls continuously and forgot to login by the time i was free it was past 1:30 pm.', NULL, 'Approved', '2024-12-24 07:35:56', '2025-01-02 17:16:19'),
(13, 12, '2025-01-02', 'Punch In', 'Hi,\r\nPlease mark attendance for me. I attended calls till 2 PM yesterday and forgot to login.\r\nThanks,', NULL, 'Approved', '2025-01-03 04:21:41', '2025-01-07 05:37:06'),
(14, 12, '2025-01-06', 'Punch In', 'I have not clocked in Yesterday, please mark attendance for me.\r\nThank you', NULL, 'Approved', '2025-01-07 06:14:31', '2025-01-09 04:15:20'),
(15, 18, '2025-01-09', 'Punch In', 'I forgot to clocked in. Please approve my attendance request.', NULL, 'Approved', '2025-01-10 04:12:32', '2025-01-15 04:36:55'),
(16, 13, '2025-01-10', 'Punch In', 'forgot to login', NULL, 'Approved', '2025-01-10 09:45:34', '2025-01-15 04:37:01'),
(17, 12, '2025-01-16', 'Punch In', 'Hi \r\nI forgot to login yesterday due to back to back calls and work on boomi. Please mark attendance for me.\r\nThank you', NULL, 'Approved', '2025-01-17 04:10:38', '2025-01-21 04:08:33'),
(18, 12, '2025-01-20', 'Punch In', 'Hi,\r\nCould you please mark attendance for, I forgot to check in on monday.', NULL, 'Approved', '2025-01-22 06:14:25', '2025-01-27 04:27:19'),
(19, 12, '2025-01-21', 'Punch In', 'Hi,\r\nCould you please mark attendance for, I forgot to check in on tuesday.', NULL, 'Approved', '2025-01-22 06:14:41', '2025-01-27 04:26:35'),
(20, 12, '2025-01-23', 'Punch In', 'Hi,\r\nI have forgot to check in with due to continuous call after vishal\'s call.', NULL, 'Approved', '2025-01-23 10:21:17', '2025-01-27 04:12:12'),
(21, 16, '2025-01-23', 'Punch In', 'I missed to clock in please approve', NULL, 'Approved', '2025-01-23 10:22:16', '2025-01-27 04:11:34'),
(22, 15, '2025-02-03', 'Punch In', 'Please don\'t approve. This is for testing purpose.', NULL, 'Deleted', '2025-01-27 07:24:16', '2025-01-30 04:35:21'),
(23, 15, '2025-01-28', 'Punch In', 'Testing purpose 1', NULL, 'Deleted', '2025-01-27 12:07:05', '2025-01-30 04:35:18'),
