(26, 20, '2025-01-31', 'Punch In', 'Couldn\'t login', NULL, 'Approved', '2025-01-31 08:13:12', '2025-01-31 08:13:26'),
(27, 15, '2024-12-25', 'Punch In', 'This is for testing purposes. please dont approve', NULL, 'Deleted', '2025-01-31 08:47:12', '2025-01-31 09:12:51'),
(28, 15, '2024-12-18', 'Punch In', 'Testing', NULL, 'Deleted', '2025-02-04 07:40:18', '2025-02-04 07:48:11'),
(29, 15, '2025-01-14', 'Punch In', 'Testing', NULL, 'Deleted', '2025-02-04 07:47:00', '2025-02-04 07:48:11'),
(30, 20, '2025-02-04', 'Punch In', 'Couldn\'t Login', NULL, 'Approved', '2025-02-04 08:50:50', '2025-02-05 10:37:02'),
(31, 17, '2025-01-03', 'Punch In', 'Signed in but not captured somehow.', NULL, 'Approved', '2025-02-07 04:43:37', '2025-02-07 06:46:25'),
(32, 12, '2025-02-07', 'Punch In', 'Hi Nithin,\r\nWe had continuous call with boomi on testing and then went on calls with Sachin and Vishal continuously, till 3pm. I didn\'t realise on check in. Please mark attendance for me on friday, Feb, 7th.\r\nThanks', NULL, 'Approved', '2025-02-10 06:33:01', '2025-02-11 04:11:36'),
