INSERT INTO `j_ob_posts` (`id`, `company_name`, `job_id`, `job_title`, `skills_required`, `experience_required`, `location`, `job_type`, `job_function`, `job_posting_date`, `application_deadline`, `contact_information`, `required_education`, `job_status`, `benefits`, `salary_range`, `work_model`, `shift_timing`, `travel_required`, `job_description`, `how_to_apply`, `created_at`, `updated_at`) VALUES
(1, 'Tech Innovators Inc.', 'TI1234567', 'Software Engineer', '[\"Java\",\"Python\",\"SQL\",\"Cloud Computing\",\"Problem Solving\"]', '3-5 years', 'New York, NY', 'Full-time', '7', '2024-12-01', '2024-12-31', '{\"email\":\"careers@techinnovators.com\",\"phone\":\"+1 (800) 555-1234\"}', 'Bachelor\'s in Computer Science or related field', 'Active', '[\"Health Insurance\",\"401(k)\",\"Paid Time Off\",\"Remote Work Options\",\"Professional Development\"]', '$90,000 - $120,000 per year', 'Hybrid (2 days in office, 3 days remote)', 'Night', '10% travel', 'We are looking for a highly skilled and motivated Software Engineer to join our team. The ideal candidate will work on developing and maintaining software solutions, ensuring high-quality code, and collaborating with cross-functional teams. The role involves both back-end and front-end development tasks, and knowledge of cloud platforms is a plus.', 'Please submit your resume and cover letter via our careers portal at careers@techinnovators.com. Include your portfolio or GitHub link, if applicable.', NULL, NULL),
(2, 'APISOD', 'JOB-0019', 'Sr. Engineer', '[\"HPH\",\"LARAVEL\"]', '5', 'Lucknow', 'Full Time', '2', '2025-01-01', '2025-01-31', '{\"email\":\"anooptri16@gmail.com\",\"phone\":null}', 'BCA', 'Active', '[\"Test Benifits\"]', '20000', 'Hybrid', 'Night', '75%', '<p><strong>Job Summary:</strong></p><p>We are seeking a skilled and motivated PHP Developer with expertise in the Laravel framework to join our dynamic development team. As a PHP Developer (Laravel), you will be responsible for building and maintaining robust, scalable web applications and working on the full software development lifecycle, from concept through to implementation and support.</p>', '<p><strong>Key Responsibilities:</strong></p><ul><li>Develop and maintain web applications using PHP and Laravel framework.</li><li>Collaborate with cross-functional teams to gather and analyze requirements.</li><li>Write clean, well-documented, and efficient code.</li><li>Design and implement new features and functionalities.</li><li>Troubleshoot, debug, and optimize applications for performance.</li><li>Ensure the security and scalability of web applications.</li><li>Work with front-end developers to integrate user-facing elements with server-side logic.</li><li>Participate in code reviews to ensure best practices and maintain code quality.</li><li>Conduct testing and debugging to ensure the functionality and performance of applications.</li><li>Keep up to date with the latest trends, technologies, and best practices in PHP development.</li></ul><p><strong>Required Skills &amp; Qualifications:</strong></p><ul><li>Proven experience as a PHP developer with strong expertise in the Laravel framework.</li><li>Solid understanding of web development, including HTML, CSS, JavaScript, and SQL.</li><li>Experience with RESTful APIs and integrating third-party services.</li><li>Familiarity with version control systems (e.g., Git).</li><li>Experience with database management systems like MySQL or PostgreSQL.</li><li>Understanding of MVC (Model-View-Controller) architecture.</li><li>Ability to work in an Agile development environment.</li><li>Strong problem-solving skills and attention to detail.</li><li>Excellent communication and collaboration skills.</li></ul><p><strong>Preferred Qualifications:</strong></p><ul><li>Knowledge of other PHP frameworks or modern web technologies.</li><li>Experience with deployment and cloud platforms (e.g., AWS, DigitalOcean).</li><li>Familiarity with Docker, CI/CD pipelines, or containerization tools.</li><li>Experience with unit testing and TDD.</li></ul>', NULL, NULL),
(5, 'Capgemini', 'Cap-341', 'HRSD Developer', '[\"UI Policy\",\"Servicenow\"]', '5', 'Hyderabad', 'Full Time', '7', '2024-12-20', '2024-12-31', '{\"email\":\"admin@apisod.ai\",\"phone\":null}', 'B.Tech', 'Active', '[\"WFH\",\"Insurance\"]', 'Not disclosed', 'Work from Home', 'Morning', '25%', '<p><strong style=\"color: var(--N800);\">ServiceNow HRSD Developer | Bangalore, Chennai, Mumbai, Pune, Hyderabad, Delhi NCR, Kolkata, Coimbatore</strong></p><p><br></p><ul><li>4+ years of experience in Servicenow Development with Servicenow Modules like HRSD</li><li>Chief technical designer for ServiceNow code and architecture, responsible for overall ServiceNow code quality</li><li>Expertise in HR domain.</li><li>Design, prototype, implement, test, and deploy business rules, technical solutions, such as client scripts, UI pages/actions/policies, scheduled job, import sets and transform maps, ACLs and notifications.</li><li>Develop custom integration components (SSO, CMDB, SAS connectors etc.) and integrate legacy systems with ServiceNow using mid-server, web services, chatops, email and other relevant technologies. Ability to apply business concepts into a technical solutions.</li><li>Develop existing and custom applications within ServiceNow including integrations with other applications.</li><li>Hands-on experience in Service Catalog/Service Portal modules.</li></ul><p><br></p><p><strong style=\"color: var(--N800);\">Primary Skills</strong></p><p><br></p><ul><li>Strong experience of ServiceNow development with HR Service Delivery.</li><li>Hands on experience in IT service management process designs.</li><li>Overarching understanding of ServiceNow Enterprise product suite.</li><li>Fundamental understanding of the key technologies relevant to the ServiceNow integration solutions.</li></ul><p><br></p>', '<p>Capgemini is a global business and technology transformation partner, helping organizations to accelerate their dual transition to a digital and sustainable world, while creating tangible impact for enterprises and society. It is a responsible and diverse group of 340,000 team members in more than 50 countries. With its strong over 55-year heritage, Capgemini is trusted by its clients to unlock the value of technology to address the entire breadth of their business needs. It delivers end-to-end services and solutions leveraging strengths from strategy and design to engineering, all fueled by its market leading capabilities in AI, cloud and data, combined with its deep industry expertise and partner ecosystem. The Group reported 2023 global revenues of 22.5 billion (Euro).</p><p><br></p><p>Capgemini in India comprises nearly 175,000 team members working across 13 locations: Bangalore, Bhubaneswar, Chennai, Coimbatore, Gandhinagar, Gurugram, Hyderabad, Kolkata, Mumbai, Noida, Pune, Salem and Tiruchirappalli.</p><p><br></p><p>Get The Future You Want | Learn more about Capgemini in India at www.capgemini.com/in-en.</p><p><strong>Company Info</strong></p><p><strong>Address:</strong></p><p><span style=\"color: var(--N600);\">Airoli Knowledge Park Plot No.IT-1, IT-2, IT-1/PT,, TTC Industrial Area, Thane-Belapur Road, Airoli,, Navi Mumbai, NAVI MUMBAI, Maharashtra, India</span></p><p><br></p>', NULL, NULL),
(3, 'APISOD Technology Private Ltd', 'TV235', 'Software Developer', '[\"JS\",\"React\",\"HTML\"]', '3', 'Hyderabad', 'Full Time', '2', '2024-12-20', '2024-12-31', '{\"email\":\"admin@apisod.ai\",\"phone\":null}', 'B.Tech', 'Active', '[\"WFH\",\"Insurance\"]', '12,00,000/- to 15,00,000/-', 'Hybrid', 'Morning', 'No', '<p>Job description details</p>', '<p>Here to apply</p>', NULL, NULL),
(4, 'Solix Technology Pvt Ltd', 'Sol-56', 'Software Engineer', '[\"HTML\",\"CSS\",\"React\"]', '3', 'Hyderabad', 'Full Time', '7', '2024-12-20', '2024-12-31', '{\"email\":\"lprasad@solix.com\",\"phone\":null}', 'B.Tech', 'Active', '[\"WFH\",\"Insurance\"]', '5,00,000 - 7,00,000', 'Work from Home', 'Morning', 'No', '<p>Testing purpose</p>', '<p>testing purpose to apply</p>', NULL, NULL),
(6, 'BUMKO', 'BUMKO-911', 'Senior Backend Developer', '[\"PHP\",\"Laravel\",\"Node.js\"]', '5', 'Ahmedabad', 'Full Time', '7', '2024-12-20', '2024-12-31', '{\"email\":\"atripathi@apisod.ai\",\"phone\":null}', 'MCA', 'Active', '[\"TA\\/DA\"]', 'INR 20,00,000-40,00,000 / year', 'Hybrid', 'Morning', 'No', '<p><strong>How To apply</strong>&nbsp;</p><p><strong>To apply for the Data Management Executive position, please follow these steps:</strong>&nbsp;</p><ol><li><strong>Prepare Your Resume:</strong>&nbsp;</li><li>Update your resume with relevant experience, highlighting skills in database management, data analysis, and Excel proficiency.&nbsp;</li><li><strong>Cover Letter (Optional):</strong>&nbsp;</li><li>Write a brief cover letter explaining why you\'re a good fit for the role and how your skills align with the responsibilities outlined in the JD.&nbsp;</li><li><strong>Submit Your Application:</strong>&nbsp;</li><li>your resume (and cover letter, if applicable) to [Email Address] or apply directly through [Application Portal].&nbsp;</li><li>your resume (and cover letter, if applicable) to [Email Address] or apply directly through [Application Portal].&nbsp;</li><li><strong>Interview Process:</strong>&nbsp;</li><li>If shortlisted, you will be contacted for an interview. Please be prepared to discuss your previous experience.&nbsp;</li><li>your approach to data management, and your skills in database systems and analysis.&nbsp;</li></ol><p>&nbsp;</p><p><strong>Job Description (JD):</strong>&nbsp;</p><p>We are seeking an experienced Data Management Executive to join our dynamic team. The ideal candidate will possess strong expertise in managing large data sets, ensuring data integrity, and generating insights for business decisions. If you have excellent analytical skills, a keen attention to detail, and experience in database management, we would love to have you on board.&nbsp;</p><p>&nbsp;</p><p><strong>Responsibilities:</strong>&nbsp;</p><ol><li><strong>Data Management:</strong>&nbsp;</li><li>Manage large sets of data and ensure accuracy and integrity across multiple sources.&nbsp;</li><li><strong>Data Quality &amp; Consistency:</strong>&nbsp;</li><li>Develop and maintain data management processes to ensure data consistency and high quality across systems.&nbsp;</li><li><strong>Data Analysis &amp; Reporting:</strong>&nbsp;</li><li>Analyze data and provide actionable insights to inform business decisions and strategies.&nbsp;</li><li>Collaboration:&nbsp;</li><li>Work closely with cross-functional teams to identify key data needs and requirements.&nbsp;</li><li>Work closely with cross-functional teams to identify key data needs and requirements.&nbsp;</li><li><strong>Reporting &amp; Visualization:</strong>&nbsp;</li><li>Create detailed reports, data visualizations, and dashboards to effectively communicate insights to stakeholders.&nbsp;</li><li><strong>Database Development &amp; Maintenance:</strong>&nbsp;</li><li>Develop and maintain database systems to enable efficient data storage and retrieval.&nbsp;</li><li><strong>Trend Identification:</strong>&nbsp;</li><li>Apply statistical and data mining techniques to identify trends and patterns in complex data sets.&nbsp;</li></ol><p><br></p>', '<p><strong style=\"color: var(--N800);\">How to apply for this opportunity</strong></p><p><br></p><ol><li>Register or login on our portal</li><li>Click \'Apply,\' upload your resume and fill in the required details.</li><li>Post this click Apply Now\' to submit your application.</li><li>Get matched and crack a quick interview with our hiring partner.</li><li>Land your global dream job and get your exciting career started!</li></ol><p><br></p><p><strong style=\"color: var(--N800);\">About Our Hiring Partner:</strong></p><p>Uplers was created with one thing in mind: Hiring and getting hired should be simple, reliable, and fast. Our AI-enabled hiring platform helps in making that connection. Our network has 1M+ deeply vetted Indian talents. With navigational ease, assisting hiring managers connect with the right Indian talent, and eliminating the longer screening process. We have created a community with our deeply vetted talents connecting with hundreds of leading companies like GitLab, Twilio, TripAdvisor, and AirBnB who have leveraged Uplers to scale their tech and digital teams quickly and cost-effectively.</p><p><br></p><p><strong style=\"color: var(--N800);\">About Uplers:</strong></p><p>Our goal is to make hiring reliable, simple, and fast. Our role will be to help all our talents find and apply for relevant opportunities and progress in their career. We will support any grievances or challenges you may face during the engagement. You will also be assigned to a dedicated Talent Success Coach during the engagement.</p><p><br></p><p>(<strong style=\"color: var(--N800);\">Note:</strong>&nbsp;There are many more opportunities apart from this on the portal. Depending on the assessments you clear, you can apply for them as well).</p>', NULL, NULL),
(7, 'Amazon', 'AMZ-844', 'Devloper', '[\"Javascript\",\"CSS\"]', '3', 'Hyderabad', 'Full Time', '7', '2024-12-25', '2025-01-10', '{\"email\":\"lprasad@apisod.ai\",\"phone\":null}', 'B.tech', 'Active', '[\"Insurance\",\"Bonus\"]', '10,00,000/- 15,00,000/-', 'Hybrid', 'Morning', 'No', '<p>Testing for handle submit navigation to job list</p>', '<p>Test</p>', NULL, NULL),
(8, 'Infosys', 'INF-081-2', 'FrontEnd Developer 2', '[\"ReactJs\",\"Javascript\",\"HTML\",\"CSS\"]', '2', 'Hyderabad', 'Full Time', '7', '2024-12-25', '2024-12-31', '{\"email\":\"lprasad@apisod.ai\",\"phone\":null}', 'B.Tech or BBA or Bacherlors in any field', 'Active', '[\"WFH\",\"Insurance\"]', '10,00,000/- to 13,00,000/-', 'Hybrid', 'Morning', 'No', '<p><span style=\"background-color: transparent;\">Key Responsibilities:</span></p><ul><li>Coordinates the review and revision of procedures, specifications and forms, such as quality manuals and standard operating procedures.</li><li>Prepares process and status reports, assigns and monitors document numbers and reviews documents for accuracy and completeness.</li><li>Coordinates the compilation and maintenance of regulatory filing documents and maintaining computerized files to support all documentation systems, including archiving documentation according to regulatory requirement</li></ul>', '<p><span style=\"color: rgb(73, 73, 73);\">Agilent Technologies, Inc. is an Equal Employment Opportunity and Affirmative Action employer. We value diversity at all levels. All individuals, regardless of personal characteristics, are encouraged to apply. All qualified applicants will receive consideration for employment without regard to sex, pregnancy, race, religion or religious creed, color, gender, gender identity, gender expression, national origin, ancestry, physical or mental disability, medical condition, genetic information, marital status, registered domestic partner status, age, sexual orientation, military or veteran status, protected veteran status, or any other basis protected by federal, state, local law, ordinance, or regulation and will not be discriminated against on these bases. Agilent Technologies, Inc., is committed to diversity in the workplace and strives to support candidates with disabilities. If you have a disability and need assistance with any part of the application or interview process or have questions about workplace accessibility, please email job_posting@agilent.com or contact +1-262-754-5030. For more information about equal employment opportunity protections, please visit www.agilent.com/en/accessibility.</span></p>', NULL, NULL),
(9, 'Apisod Technologies Private Limited', 'APISOD-20241226', 'DevOps Engineer', '[\"Terraform\",\"Networking Kubernates\",\"Azure Devops\",\"Docker\",\"Linux Infrastructure\",\"Ci\\/Cd\",\"Azure Cloud Services\",\"Powershell Scripting\"]', '5', 'Noida', 'Full Time', '7', '2024-12-26', '2024-12-31', '{\"email\":\"admin@apisod.ai\",\"phone\":null}', 'B.tech (Any Relevant)', 'Active', '[\"All\"]', '16,00,000 - 18,00,000', 'Hybrid', 'Regular', 'No', '<h3><strong>Job Responsibilities: </strong></h3><p><br></p><ol><li>Understand Managed Services customer solutions, architecture, requirements from a business &amp; technical context.</li><li>Deploying and managing Adeptia proprietary applications in customer on-prem/Adeptia hosted cloud in Azure by adapting CI/CD pipeline using Devops tools chain (e.g., Git, Azure-DevOps, Git and Terraform).</li><li>Work with DevOps team to build multi-region highly available systems in Azure, make faster DR, ensure Security like EDR (Endpoint Detection &amp; Response).</li><li>Work extensively with Kubernetes and topics such as Node, Pods, Services, Ingress, PV/PVC, Statefulset, Configmap, Secret etc.</li><li>Work with a team to build and create multiple Azure services for continuous deployment of applications in DEV/QA/PROD environments based on Containerized Technology.</li><li>Use Terraform modules to automate infrastructure provisioning, terraform scripts to set up Azure and automate the deployment of Adeptia solution &amp; infrastructure.</li><li>Work on Azure API, API Gateway, App Services and Azure Open AI.</li><li>Monitor the performance of the Adeptia application and solution for computing, storage, database performance and network resource utilization and performance degradation.</li><li>Work with a team in configuration changes based on industry best practices to the growing solution and system needs.</li><li>Perform regularly scheduled maintenance tasks to ensure optimal system and application performance</li><li>Follow Agile methodology such as Scrum, Kanban for faster and continuous delivery.</li><li>Work closely with the Development/Implementation team to review requirements and Design docs and discuss Testing Scope for enhancements, fixes</li><li>Collaborate with System Architect on how to best design their cloud applications for optimal scaling including content caching, compute optimizations, continuous integration, and delivery pipeline, load balancer setup.</li></ol>', '<h3>How to Apply:</h3><p><br></p><p>To apply for this position, </p><p><br></p><ul><li>Please visit <u>www.apisod.ai/job</u> to view the job opening and submit your application directly through the site.</li><li>For any queries, feel free to reach out to us at <u>admin@apisod.ai.</u></li></ul>', NULL, NULL),
