DELIMITER $$
CREATE TRIGGER `trg_insert_employee_leave_balance` AFTER INSERT ON `employees` FOR EACH ROW BEGIN
    DECLARE months_diff INT;
    SET months_diff = TIMESTAMPDIFF(MONTH, NEW.DateOfJoining, CONCAT(YEAR(CURDATE()), '-12-31'));
    VALUES (NEW.EmployeeID, YEAR(CURDATE()), 7, LEAST(30, CEIL(months_diff * 1.5)), 2, 5, 5, 30);
    
    VALUES (NEW.EmployeeID, LEAST(30, CEIL(months_diff * 1.5)), 0, LEAST(30, CEIL(months_diff * 1.5)));
END
$$
DELIMITER ;

